input.old_string:
     * Normalize {@code telephone} to E.164: keep an explicit leading '+' and its country
     * code when present, otherwise assume '+61' and drop a single leading '0' from the
     * national digits. Spaces, dashes and brackets are stripped. The result is returned
     * only when it holds 8 to 15 digits after the '+', so an unconvertible number stays
     * as its cleaned form and is rejected by validation.
     */
    static String toE164(String telephone) {
        if (telephone == null) {
            return null;
        }
        String cleaned = telephone.replaceAll("[\\s()\\-]", "");
        String digits;
        if (cleaned.startsWith("+")) {
            digits = cleaned.substring(1);
        }
        else {
            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
            digits = "61" + national;
        }
        if (!digits.matches("[0-9]{8,15}")) {
            return cleaned;
        }
        return "+" + digits;
    }
}

input.new_string:
     * Normalize {@code telephone} to E.164: keep an explicit leading '+' and its country
     * code when present, otherwise assume '+61' and drop a single leading '0' from the
     * national digits. Spaces, dashes and brackets are stripped. The result is returned
     * only when its national-number length is valid for the country code (see
     * {@link #hasValidNationalLength}), so an unconvertible number is returned without a
     * '+' and is rejected by validation.
     */
    static String toE164(String telephone) {
        if (telephone == null) {
            return null;
        }
        String cleaned = telephone.replaceAll("[\\s()\\-]", "");
        String digits;
        if (cleaned.startsWith("+")) {
            digits = cleaned.substring(1);
        }
        else {
            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
            digits = "61" + national;
        }
        if (!hasValidNationalLength(digits)) {
            return digits;
        }
        return "+" + digits;
    }

    /**
     * True when {@code digits} (country code plus national number, no '+') has a national
     * length allowed for its country code: '+61' requires 9 national digits and '+1'
     * requires 10; any other country falls back to the generic 8-to-15 total-digit range.
     */
    private static boolean hasValidNationalLength(String digits) {
        if (!digits.matches("[0-9]{8,15}")) {
